<?php require_once __DIR__.'/../config/bootstrap.php'; Auth::requireLogin(); $report=new Report($pdo); $ledger=new Ledger($pdo); $error=$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['_csrf']??null);try{if(($_POST['action']??'post')==='reverse'){$result=$ledger->reverse((int)$_POST['transaction_id'],(int)Auth::user()['id']);$success='Transaction reversed: '.$result['reference'];}else{$result=$ledger->post(['customer_id'=>(int)($_POST['customer_id']??0),'funding_source_id'=>(int)($_POST['funding_source_id']??0),'transaction_type'=>trim($_POST['transaction_type']),'amount'=>$_POST['amount'],'currency'=>strtoupper($_POST['currency']?:'USD'),'description'=>trim($_POST['description']??''),'idempotency_key'=>trim($_POST['idempotency_key']),'entries'=>[['account_id'=>(int)$_POST['debit_account'],'debit'=>$_POST['amount'],'credit'=>0],['account_id'=>(int)$_POST['credit_account'],'debit'=>0,'credit'=>$_POST['amount']]]],(int)Auth::user()['id']);$success=$result['duplicate']?'Duplicate prevented; existing transaction returned.':'Transaction posted: '.$result['reference'];}}catch(Throwable $e){$error=$e->getMessage();}}
$customers=$pdo->query("SELECT id,name FROM customers WHERE status='active' ORDER BY name")->fetchAll();$sources=$pdo->query("SELECT id,name FROM funding_sources WHERE status='active' ORDER BY name")->fetchAll();$accounts=$pdo->query("SELECT id,account_code,name FROM accounts WHERE status='active' ORDER BY account_code")->fetchAll();$rows=$report->transactions($_GET); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transactions · LedgerFlow</title><link rel="stylesheet" href="assets/app.css"></head><body><aside class="sidebar"><div class="brand">Ledger<span>Flow</span></div><nav><a href="index.php">Dashboard</a><a class="active" href="transactions.php">Transactions</a><a href="customers.php">Customers</a><a href="funding_sources.php">Funding Sources</a><a href="reports.php">Reports</a><a href="api_docs.php">API Docs</a></nav><div class="side-bottom"><span><?=e(Auth::user()['name'])?></span><a href="logout.php">Sign out</a></div></aside><main class="main"><header><div><p class="eyebrow">LEDGER</p><h1>Transactions</h1><p class="muted">Post balanced journal entries with duplicate protection.</p></div></header><?php if($success): ?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif;?><section class="panel"><div class="panel-head"><h2>Post transaction</h2></div><form method="post" class="grid-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Customer<select name="customer_id"><option value="0">None</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Funding source<select name="funding_source_id"><option value="0">None</option><?php foreach($sources as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Transaction type<select name="transaction_type"><option value="payment">Payment</option><option value="deposit">Deposit</option><option value="refund">Refund</option><option value="expense">Expense</option></select></label><label>Amount<input type="number" step="0.01" min="0.01" name="amount" required></label><label>Currency<input name="currency" value="USD" maxlength="3" required></label><label>Idempotency key<input name="idempotency_key" value="<?=e('web-'.bin2hex(random_bytes(5)))?>" required></label><label>Debit account<select name="debit_account" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['account_code'].' · '.$a['name'])?></option><?php endforeach;?></select></label><label>Credit account<select name="credit_account" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['account_code'].' · '.$a['name'])?></option><?php endforeach;?></select></label><label class="wide">Description<textarea name="description" rows="3"></textarea></label><div class="wide"><button class="btn primary">Post transaction</button></div></form></section><section class="panel"><div class="panel-head"><h2>Transaction history</h2><form class="inline-form"><select name="customer_id"><option value="">All customers</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=((string)($_GET['customer_id']??''))===(string)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><input type="date" name="from" value="<?=e($_GET['from']??'')?>"><input type="date" name="to" value="<?=e($_GET['to']??'')?>"><select name="type"><option value="">All types</option><option <?=($_GET['type']??'')==='payment'?'selected':''?>>payment</option><option <?=($_GET['type']??'')==='deposit'?'selected':''?>>deposit</option><option <?=($_GET['type']??'')==='expense'?'selected':''?>>expense</option><option <?=($_GET['type']??'')==='refund'?'selected':''?>>refund</option></select><button class="btn">Filter</button></form></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Type</th><th>Amount</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['transaction_reference'])?></td><td><?=e($r['customer_name']??'—')?></td><td><?=e($r['transaction_type'])?></td><td><?=money($r['amount'],$r['currency'])?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e($r['created_at'])?></td><td><?php if($r['status']==='posted'): ?><form method="post" onsubmit="return confirm('Reverse this posted transaction?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reverse"><input type="hidden" name="transaction_id" value="<?=$r['id']?>"><button class="btn danger" type="submit">Reverse</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
